function str(values: EditorValues, key: string) { const value = values[key]; return typeof value === "string" ? value : ""; }
function flag(values: EditorValues, key: string) { return values[key] === true; }
function stringList(values: EditorValues, key: string) { const value = values[key]; return Array.isArray(value) ? value : []; }
function Button({ children, icon, onClick, tone = "default", disabled = false }: { children: ReactNode; icon?: ReactNode; onClick?: () => void; tone?: "default" | "primary" | "danger" | "ghost"; disabled?: boolean }) { return <button type="button" className={`btn btn-${tone}`} onClick={onClick} disabled={disabled}>{icon}{children}</button>; }
function Badge({ value }: { value: string | null | undefined }) { const text = value ?? "—"; const good = ["ENABLED","ACTIVE","SUCCESS","PASSED","SUCCEEDED","PASS","READY","COMPLETED","VISIBLE","PUBLISHED","BASELINE_CREATED"].includes(text); const bad = ["FAILED","CRITICAL","MISMATCH","ABORTED","DEAD_LETTER","PARTIAL_FAILED"].includes(text); const warn = ["PARTIAL","OUTDATED","ISSUES","WARNING","RUNNING","LOADING","VALIDATING","PENDING","PROBING","DIFF_GENERATED"].includes(text); return <span className={`badge ${good ? "badge-good" : bad ? "badge-bad" : warn ? "badge-warn" : "badge-muted"}`}>{text}</span>; }
function PageHeader({ page, actions }: { page: AppPage; actions?: ReactNode }) { const [title, description] = titles[page] ?? titles.dashboard!; return <div className="page-header"><div><h1>{title}</h1><p>{description}</p></div>{actions && <div className="actions">{actions}</div>}</div>; }
function SearchBar({ query, setQuery, placeholder = "搜索" }: { query: string; setQuery: (value: string) => void; placeholder?: string }) { return <label className="search"><SearchOutlined /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={placeholder} /></label>; }
function Card({ title, note, actions, children }: { title?: string; note?: string; actions?: ReactNode; children: ReactNode }) { return <section className="card">{(title || actions) && <header><div>{title && <h2>{title}</h2>}{note && <p>{note}</p>}</div>{actions && <div className="actions">{actions}</div>}</header>}<div className="card-body">{children}</div></section>; }
function Table({ headers, rows, empty = "暂无数据" }: { headers: string[]; rows: ReactNode[][]; empty?: string }) { return <div className="table-wrap"><table><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row,index) => <tr key={index}>{row.map((cell,cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>) : <tr><td colSpan={headers.length}><div className="empty">{empty}</div></td></tr>}</tbody></table></div>; }
function Toggle({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) { return <button type="button" role="switch" aria-checked={checked} aria-label={label} onClick={onChange} className={`switch ${checked ? "is-on" : ""}`}><span /></button>; }
function Notice({ children, tone = "info" }: { children: ReactNode; tone?: "info" | "warn" | "danger" | "success" }) { return <div className={`notice notice-${tone}`}>{children}</div>; }
function Metric({ label, value, hint, icon }: { label: string; value: number | string; hint: string; icon: ReactNode }) { return <article className="metric"><span>{icon}</span><div><small>{label}</small><strong>{value}</strong><p>{hint}</p></div></article>; }

function scheduleLabel(policy: DatasetPolicyValue) {
  if (policy.scheduleMode === "INHERIT") return "继承全局";
  if (policy.scheduleMode === "MANUAL") return "人工";
  if (policy.scheduleMode === "EVERY_N_HOURS") return `每 ${policy.scheduleIntervalHours} 小时`;
  return `CRON ${policy.scheduleCron}`;
}
function stableHash(value: string) { let hash = 0; for (let index = 0; index < value.length; index += 1) hash = ((hash << 5) - hash + value.charCodeAt(index)) | 0; return Math.abs(hash); }
function staggeredCron(institutionCode: string, datasetCode: string, intervalHours: number) { const hash = stableHash(`${institutionCode}:${datasetCode}`); const minute = hash % 60; const startHour = Math.floor(hash / 60) % intervalHours; return `0 ${minute} ${startHour}/${intervalHours} * * ?`; }
function everyHoursLabel(intervalHours: number, cron: string) { const parts = cron.split(/\s+/); const minute = Number(parts[1] ?? 0); const hour = Number((parts[2] ?? "0").split("/")[0]); return `每 ${intervalHours} 小时 · ${String(hour).padStart(2,"0")}:${String(minute).padStart(2,"0")} 起`; }
function aggregateTargetTestStatus(endpoints: TargetEndpoint[]): TestStatus {
  const enabled = endpoints.filter((endpoint) => endpoint.enabled);
  if (!enabled.length || enabled.every((endpoint) => endpoint.testStatus === "UNTESTED")) return "UNTESTED";
  if (enabled.every((endpoint) => endpoint.testStatus === "SUCCESS")) return "SUCCESS";
  if (enabled.every((endpoint) => endpoint.testStatus === "FAILED")) return "FAILED";
  return "PARTIAL";
}
function aggregateTargetTestError(status: TestStatus, endpoints: TargetEndpoint[]) {
  if (status !== "PARTIAL" && status !== "FAILED") return "";
  const failed = endpoints.filter((endpoint) => endpoint.enabled && endpoint.testStatus !== "SUCCESS").map((endpoint) => `FE #${endpoint.ordinal} ${endpoint.host}:${endpoint.queryPort}`);
  return failed.length ? `未通过：${failed.join("；")}` : "部分 FE 未通过测试";
}

