  const activeIndependentValidationForTask = (taskId: string) => validationSeed.find((row) => row.taskId === taskId && ["MANUAL","MANUAL_RECHECK","SCHEDULED"].includes(row.trigger) && ["PENDING","RUNNING"].includes(row.status));
