    if (!dataset || dataset.status !== "ACTIVE") return "当前 Dataset 不是 ACTIVE。"; if (!route || route.status !== "ENABLED" || route.structureStatus !== "PASSED") return "当前 Route 不是 ENABLED + PASSED。"; if (!source || source.status !== "ENABLED") return "当前 Source 未启用。"; if (!target || target.status !== "ENABLED") return "当前 Target 未启用。"; if (!target.endpoints.some((endpoint) => endpoint.enabled)) return "当前 Target 没有启用的 FE Endpoint。"; return "";
